    "html": "<!doctype html>\n<html lang=\"vi\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n  <title>Đăng Nhập Tài Khoản - F1Genz Store</title>\n  <style>\n    *, *::before, *::after { box-sizing: border-box; }\n    html, body { margin: 0; padding: 0; font-family: -apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, Helvetica, Arial, sans-serif; color: #2d3436; background: #fdfdfd; font-size: 14px; line-height: 1.5; }\n    a { color: inherit; text-decoration: none; }\n    img { max-width: 100%; display: block; }\n    .container { width: 100%; max-width: 1200px; margin: 0 auto; padding: 0 15px; }\n    .row { display: flex; flex-wrap: wrap; margin: 0 -15px; }\n    .col-12 { width: 100%; padding: 0 15px; }\n    .header-demo { background: #ffffff; border-bottom: 1px solid #e2e8f0; padding: 12px 0; }\n    .header-inner { display: flex; align-items: center; justify-content: space-between; }\n    .logo-demo { font-size: 20px; font-weight: 700; color: #d63031; text-transform: uppercase; letter-spacing: 0.5px; }\n    .nav-demo { display: flex; gap: 20px; font-weight: 500; }\n    .footer-demo { background: #1e272e; color: #d2d7d9; padding: 40px 0 20px; margin-top: 40px; }\n    .footer-grid { display: flex; flex-wrap: wrap; gap: 30px; justify-content: space-between; }\n    .footer-col { flex: 1; min-width: 220px; }\n    .footer-col h4 { color: #ffffff; margin-top: 0; margin-bottom: 15px; font-size: 16px; }\n    .footer-col ul { list-style: none; padding: 0; margin: 0; }\n    .footer-col li { margin-bottom: 8px; font-size: 13px; }\n    .footer-bottom-copy { border-top: 1px solid #2f3640; margin-top: 30px; padding-top: 20px; text-align: center; font-size: 13px; color: #718093; }\n    \n    .auth-page { min-height: 80vh; display: flex; align-items: center; justify-content: center; padding: 40px 15px; }\n    .auth-card { background: #fff; border: 1px solid #e2e8f0; border-radius: 10px; padding: 35px 30px; width: 100%; max-width: 440px; box-shadow: 0 4px 15px rgba(0,0,0,0.05); }\n    .auth-card h2 { margin-top: 0; margin-bottom: 25px; text-align: center; color: #2d3436; }\n    .form-group-floating { position: relative; margin-bottom: 20px; }\n    .floating-input { width: 100%; height: 50px; padding: 14px 16px; border: 1px solid #cbd5e1; border-radius: 6px; font-size: 15px; color: #2d3436; }\n    .floating-label-target { position: absolute; left: 16px; top: 14px; font-size: 15px; color: #d63031; font-weight: 600; pointer-events: none; }\n    .btn-submit-login { width: 100%; height: 48px; background: #d63031; color: #fff; border: none; border-radius: 6px; font-size: 16px; font-weight: 600; cursor: pointer; margin-top: 10px; }\n  \n  </style>\n</head>\n<body>\n  \n    <header class=\"header-demo\"><div class=\"container\"><span class=\"logo-demo\">F1Genz Store</span></div></header>\n    <div class=\"auth-page\">\n      <div class=\"auth-card\">\n        <h2>Đăng Nhập Khách Hàng</h2>\n        <div class=\"form-group-floating\" id=\"target-floating-group\">\n          <input type=\"email\" class=\"floating-input\" id=\"target-input-field\" value=\"khachhang-f1genz@thoitrang.vn\">\n          <label class=\"floating-label-target\" id=\"target-label\">Địa Chỉ Email / Số Điện Thoại</label>\n        </div>\n        <div class=\"form-group-floating\">\n          <input type=\"password\" class=\"floating-input\" value=\"12345678\" style=\"padding-top: 20px;\">\n          <label style=\"position: absolute; left: 16px; top: 6px; font-size: 11px; color: #64748b;\">Mật Khẩu</label>\n        </div>\n        <button class=\"btn-submit-login\">Đăng Nhập Ngay</button>\n      </div>\n    </div>\n  \n  \n</body>\n</html>"
